"""Balanced B0011 source review, preserving partial-access distinctions."""
import json
import ledger as L
from review_batch_0001 import evidence
NOTES=[('10.1126/science.1250944', 'design_sources_reviewed', 'design_bearing', 'Main printedpp65–68 Design/ConnectorDesigns/PolyhedraAssembly; SI S2 materials, contents and TablesS1–S7 headings', 'Tripod monomers have three approximately50nm arms, each16parallel helices explicitly on honeycomb lattice, plus two-helix struts and variable vertex helices. p8064 scaffold is specified in SI. Separate monomer design from assembled tetrahedron/prisms/cube. Tetrahedron uses X-X/Y-Y/Z-Z connections; other assemblies X-X/Y-Z. Long30nt versus short11nt connectors have different binding segments. Actual pentagonal/hexagonal products required90-90-120 and90-90-140 designs rather than ideal108/120 final angles. Missing-strut/vertex controls are distinct composition variants. SI lists DNA-PAINT strands separately from six structural sequence tables including two cube connector sets. Full tables/routing/native sources not yet verified. Honeycomb arms are explicit; wireframe assembly outline alone is not a lattice exclusion.'), ('10.1039/c3ra45676e', 'metadata_screened', 'design_bearing', 'Publisher abstract and article information retrieved via search', 'Publisher abstract establishes an origami frame carrying two duplexes with3–6G-G mismatches, with ligand-induced synapsis and streptavidin localization. This supports experimental design use but not exact frame source completeness. First publication20December2013 precedes2014issue; preserve both. Direct landing/fulltext access failed; two guessed SI filenames returned404, which does not establish supplement unavailability. Publisher lists one PDF and two movies; actual links remain to resolve.'), ('10.1063/1.4870519', 'metadata_screened', 'uncertain', 'PubMed primary abstract metadata; direct PMC access challenge', 'Primary abstract reports electron-induced breaks/crosslinks in plasmid DNA films. Full Methods and origami citation context remain uninspected; retain uncertain rather than infer exclusion from abstract. PMCID4716823 provides an acquisition lead, but direct browser access returned a challenge. Date metadata gives issue15April2014 versus legacy1April2014; first-publication date remains to verify.')]
def main():
 pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 for key,stage,rel,loc,note in NOTES:
  p=pubs[key]
  evs=[evidence(L.HERE/'batch_0011_rotation_second_search.json','https://doi.org/'+key,loc)]
  if key=='10.1126/science.1250944':
   evs=[evidence(L.ROOT/'assets/research-20261105/iinuma-2014-cage-main.pdf','https://yin.hms.harvard.edu/publications/2014.cage.pdf',loc),evidence(L.ROOT/'assets/research-20261105/iinuma-2014-cage-si.pdf','https://yin.hms.harvard.edu/publications/2014.cage.sup1.pdf','SI S2 and structural-table headings; full sequence validation pending')]
  p.update(review_stage=stage,relevance=rel,publication_type=['journal_article'],design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',evidence=evs,rationale=note,unresolved_questions=['Acquire/review full primary Methods and all required source maps/sequences; retain lattice and broad relevance separately.','Enumerate complete bibliographies and reconcile exact design parents and variants.'],reviewer='Codex named primary sections or explicitly limited abstract inspection',run_id='B0011',date=L.DATE)
  if key=='10.1039/c3ra45676e':p['date_evidence']={'date':'2013-12-20','issue_year':2014,'primary_verified':True,'source':'Publisher article information retained in batch_0011_rotation_second_search.json'}
  L.upsert('publication_reviews',p,'Record source-backed design distinctions, date correction and unresolved access cases')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0011');action='Reviewed tripod main/SI and screened Gquad/strand-break primary abstracts under partial access:22/25first passes.'
 if action not in b['completed_actions']:b['completed_actions'].append(action)
 b.update(after_counts=L.counts(),validation=[L.validate()],next_queue=['Review3remaining B0011records: nanoparticle weighing, lithography review, tensegrity review','Resolve frame supplement links and strand-break fulltext; tripod variant/source audit','Continue FNANO2012/abstracts, forward citations and author histories'])
 L.upsert('batches',b,'Checkpoint22/25; access limitations are not exclusions')
 L.atomic(L.HERE/'batch_0011_rotation_second_audit.json',json.dumps(dict(batch_id='B0011',first_pass_count=22,input_count=25,validation=L.validate(),counts=L.counts()),indent=2)+'\n')
 print(L.validate())
if __name__=='__main__':main()
